CREATE POLICY "Users can view own project images files" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'project-images' AND auth.uid()::text = (storage.foldername(name))[1]);
CREATE POLICY "Users can upload own project images files" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'project-images' AND auth.uid()::text = (storage.foldername(name))[1]);
CREATE POLICY "Users can update own project images files" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'project-images' AND auth.uid()::text = (storage.foldername(name))[1]);
CREATE POLICY "Users can delete own project images files" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'project-images' AND auth.uid()::text = (storage.foldername(name))[1]);